          timeLeft--;
          countdownEl.textContent = timeLeft;
          if (timeLeft === 0) {
            clearInterval(timer);
          }
        }
      }, 1000);

      pauseBtn.addEventListener('click', () => {
        isPaused = !isPaused;
        pauseBtn.textContent = isPaused ? '[RESUME AUTO-REDIRECT]' : '[PAUSE AUTO-REDIRECT]';
      });
    }

    const tsEl = document.getElementById('audit-ts');
    if (tsEl) {
